package com.onlinelibrary.service.impl;
import com.onlinelibrary.dao.*; import com.onlinelibrary.dao.impl.*; import com.onlinelibrary.exception.*; import com.onlinelibrary.model.*; import com.onlinelibrary.service.LibraryService; import com.onlinelibrary.util.*;
import java.sql.SQLException; import java.util.*;
public class LibraryServiceImpl implements LibraryService {
 private final UserDAO users=new UserDAOImpl(); private final BookDAO books=new BookDAOImpl(); private final TransactionDAO transactions=new TransactionDAOImpl(); private final SearchHistoryDAO searches=new SearchHistoryDAOImpl(); private final NotificationDAO notices=new NotificationDAOImpl(); private final ReportDAO reports=new ReportDAOImpl();
 public User authenticate(String email,String password)throws Exception{User u=users.findByEmail(email).orElseThrow(()->new InvalidLoginException("Invalid email or password"));if(!"ACTIVE".equals(u.getStatus())||!PasswordUtil.verify(password,u.getPasswordHash()))throw new InvalidLoginException("Invalid email or password");u.setPasswordHash(null);return u;}
 public List<Book> searchBooks(long memberId,String text,String title,String author,String genre)throws Exception{List<Book> found=books.search(title,author,genre);searches.save(memberId,text,title,author,genre);return found;}
 /** JVM guard narrows contention locally; SELECT FOR UPDATE and SQL constraints provide cross-instance consistency. */
 public synchronized long borrow(long memberId,long bookId)throws Exception{try{return transactions.borrow(memberId,bookId,DBConnection.borrowLimit(),DBConnection.loanDays());}catch(SQLException e){String m=e.getMessage();if(m!=null&&m.contains("BOOK_UNAVAILABLE"))throw new BookUnavailableException("No available copy remains");if(m!=null&&m.contains("BORROW_LIMIT"))throw new BorrowLimitExceededException("Borrowing limit reached");if(m!=null&&m.contains("BOOK_MISSING"))throw new BookNotFoundException("Book not found");throw e;}}
 public void returnBook(long memberId,long transactionId)throws Exception{try{transactions.returnBook(memberId,transactionId);}catch(SQLException e){if(e.getMessage()!=null&&e.getMessage().contains("TRANSACTION_NOT_ACTIVE_OR_NOT_OWNED"))throw new TransactionNotFoundException("Active borrowing not found for this member");throw e;}}
 public List<LibraryTransaction> history(long memberId)throws Exception{return transactions.history(memberId);} public List<Book> books()throws Exception{return books.findAll();} public ReportSummary report()throws Exception{return reports.summary();}
 public UserDAO userDAO(){return users;} public BookDAO bookDAO(){return books;} public TransactionDAO transactionDAO(){return transactions;} public SearchHistoryDAO searchDAO(){return searches;} public NotificationDAO notificationDAO(){return notices;} public NotificationPreferenceDAO preferences(){return new NotificationPreferenceDAOImpl();} public ReportDAO reportDAO(){return reports;}
}
